"use client";
import React, { useState, useEffect, useMemo, useCallback } from "react";
import { Search, Loader2 } from "lucide-react";
import axios from "axios";
import Navbar from "../../../components/Navbar";

// --- Constants ---
const FUNDS_PER_PAGE = 15;
const API_URL = "/api/funds";

// --- Fund House Logos ---
const logos = {
  axis: "data:image/png;base64,",
  icici: "data:image/png;base64,",
  hdfc: "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTI5UTQcouxStCDZGqaIphRXoGK5OFvQeL3ZQ&s",
  sbi: "data:image/png;base64,",
  nippon: "https://cdn.freebiesupply.com/logos/large/2x/nippon-life-insurance-logo-png-transparent.png",
  kotak: "data:image/png;base64,",
  aditya: "data:image/jpeg;base64,",
  mirae: "data:image/png;base64,",
  franklin: "data:image/jpeg;base64,",
  tata: "data:image/png;base64,",
  Grindlays :"data:image/png;base64,",
  quant:"data:image/png;base64,",
  default: "https://upload.wikimedia.org/wikipedia/commons/a/ac/No_image_available.svg",

};

// --- Helper: Get fund logo based on scheme name ---
const getFundLogo = (schemeName) => {
  const name = schemeName.toLowerCase();
  if (name.includes("axis")) return logos.axis;
  if (name.includes("icici")) return logos.icici;
  if (name.includes("hdfc")) return logos.hdfc;
  if (name.includes("sbi")) return logos.sbi;
  if (name.includes("nippon")) return logos.nippon;
  if (name.includes("kotak")) return logos.kotak;
  if (name.includes("aditya")) return logos.aditya;
  if (name.includes("mirae")) return logos.mirae;
  if (name.includes("franklin")) return logos.franklin;
  if (name.includes("tata")) return logos.tata;
  if (name.includes("Grindlays")) return logos.Grindlays;
  if (name.includes("Quant")) return logos.quant;
  return logos.default;
};

// --- Page Wrapper ---
const PageWrapper = ({ children }) => (
  <div className="min-h-screen bg-gray-50 font-sans">
    <Navbar />
    <div className="container mx-auto px-4 py-8 md:py-12">{children}</div>
  </div>
);

// --- Single Fund Row ---
const FundRow = ({ fund, isEven }) => {
  const logoUrl = useMemo(() => getFundLogo(fund.schemeName), [fund.schemeName]);

  return (
    <div
      onClick={() => (window.location.href = `/mutual-funds/${fund.schemeCode}`)}
      className={`flex items-center justify-between py-4 px-4 cursor-pointer rounded-lg transition-all duration-150 ${
        isEven ? "bg-white hover:bg-green-50" : "bg-gray-50 hover:bg-green-100"
      }`}
    >
      {/* Logo + Title */}
      <div className="flex items-center space-x-4">
        <img
          src={logoUrl}
          alt={fund.schemeName}
          className="w-10 h-10 object-cover border border-gray-200 bg-white  rounded-md"
        />
        <div className="flex flex-col justify-center">
          <p className="text-base font-semibold text-gray-800 hover:text-[#00BFA5] leading-tight">
            {fund.schemeName}
          </p>
          <p className="text-xs text-gray-500 mt-1">Mutual Fund</p>
        </div>
      </div>
    </div>
  );
};

// --- Main Page ---
const MutualFundsPage = () => {
  const [allFunds, setAllFunds] = useState([]);
  const [filteredFunds, setFilteredFunds] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [isLoading, setIsLoading] = useState(true);
  const [isSearching, setIsSearching] = useState(false);

  // Fetch Funds
  useEffect(() => {
    const fetchFunds = async () => {
      setIsLoading(true);
      try {
        const res = await axios.get(API_URL);
        if (Array.isArray(res.data)) {
          setAllFunds(res.data);
          setFilteredFunds(res.data);
        }
      } catch (err) {
        console.error("Error fetching funds:", err);
      } finally {
        setIsLoading(false);
      }
    };
    fetchFunds();
  }, []);

  // Search Logic
  useEffect(() => {
    setCurrentPage(1);
    setIsSearching(true);
    const handler = setTimeout(() => {
      const lowerTerm = searchTerm.toLowerCase().trim();
      setFilteredFunds(
        lowerTerm === ""
          ? allFunds
          : allFunds.filter((f) => f.schemeName.toLowerCase().includes(lowerTerm))
      );
      setIsSearching(false);
    }, 300);
    return () => clearTimeout(handler);
  }, [searchTerm, allFunds]);

  // Pagination
  const totalPages = Math.ceil(filteredFunds.length / FUNDS_PER_PAGE);
  const fundsOnPage = useMemo(() => {
    const startIndex = (currentPage - 1) * FUNDS_PER_PAGE;
    return filteredFunds.slice(startIndex, startIndex + FUNDS_PER_PAGE);
  }, [filteredFunds, currentPage]);

  const goToPage = useCallback(
    (page) => {
      if (page >= 1 && page <= totalPages) {
        setCurrentPage(page);
        window.scrollTo({ top: 0, behavior: "smooth" });
      }
    },
    [totalPages]
  );

  return (
    <PageWrapper>
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="bg-white p-4 md:p-6 rounded-xl shadow-lg mb-8 border  border-gray-100 text-center">
          <h1 className="text-3xl font-bold text-gray-800 mb-4">Explore Mutual Funds</h1>
          <div className="flex items-center bg-gray-50 rounded-lg px-4 py-3 border border-transparent focus-within:border-[#00D09C] transition-colors duration-200 w-full md:w-2/3 mx-auto shadow-inner">
            <Search className="w-5 h-5 text-gray-500 mr-3" />
            <input
              type="text"
              placeholder="Search mutual funds (e.g., ICICI, Axis, SBI)"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="bg-transparent text-base w-full focus:outline-none placeholder-gray-400 font-medium"
            />
            {isSearching && <Loader2 className="w-5 h-5 text-[#00D09C] animate-spin ml-3" />}
          </div>
           <div className="w-full text-left text-sm text-gray-500 mt-1">
      Showing {filteredFunds.length} mutual funds
    </div>
        </div>

        {/* Fund List */}
        <div className="bg-white rounded-xl shadow-lg border border-gray-100 divide-y divide-gray-100">
          {isLoading ? (
            <div className="p-10 text-center text-gray-500">
              <Loader2 className="w-8 h-8 text-[#00D09C] animate-spin mx-auto mb-3" />
              Loading mutual funds...
            </div>
          ) : filteredFunds.length === 0 ? (
            <div className="p-10 text-center text-gray-500">No mutual funds found.</div>
          ) : (
            fundsOnPage.map((fund, i) => <FundRow key={fund.schemeCode} fund={fund} isEven={i % 2 === 0} />)
          )}

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="p-4 flex justify-between items-center bg-white rounded-b-xl border-t border-gray-100">
              <button
                onClick={() => goToPage(currentPage - 1)}
                disabled={currentPage === 1}
                className="px-4 py-2 text-sm font-semibold text-gray-600 bg-gray-100 rounded-lg hover:bg-gray-200 disabled:opacity-50 transition"
              >
                Previous
              </button>
              <span className="text-sm text-gray-600">
                Page {currentPage} of {totalPages}
              </span>
              <button
                onClick={() => goToPage(currentPage + 1)}
                disabled={currentPage === totalPages}
                className="px-4 py-2 text-sm font-semibold text-gray-600 bg-gray-100 rounded-lg hover:bg-gray-200 disabled:opacity-50 transition"
              >
                Next
              </button>
            </div>
          )}
        </div>
      </div>
    </PageWrapper>
  );
};

export default MutualFundsPage;
